            // [46] BB\script\output\_sce04_c401_0020_eng#17
            entryTranslators[@"BB\script\output\_sce04_c401_0020_eng#17"] = (s) => {
                R(ref s, "Something on your mind, <E049><E003 8><E341>Governor Caidin?", "Quelque chose vous préoccupe, <E049><E003 8><E341>Directeur Caidin ?");
                R(ref s, "It looked as though you were lost in thought there for a\r\nmoment.", "Vous sembliez être plongé dans vos pensées un instant.");
                R(ref s, "Och, <E049><E003 20><E025 2>I cannae relax when I'm no at the prison, <E049><E003 6><E025 3>do ya ken?<E049><E003 12>\r\n<E025 2>I'm all het up worryin' aboot inmates escapin'...", "Oh, <E049><E003 20><E025 2>j'peux point décompresser quand j'suis pas à la prison, <E049><E003 6><E025 3>voyez-vous ?<E049><E003 12>\r\n<E025 2>J'suis tout angoissé à l'idée que des taulards s'font la malle...");
                R(ref s, "I thought that Barclay was the most secure prison in all\r\nof Britain?", "Je croyais que Barclay était la prison la plus sûre de toute\r\nla Grande-Bretagne ?");
                R(ref s, "A-<E049><E003 10><E025 1><E335>Aye, <E049><E003 8>that's right,<E049><E003 6><E025 2> it is!<E049><E003 16>\r\n<E025 3>I'm...<E049><E003 16><E025 2><E341>sure I dinnae ought worry...", "O... <E049><E003 10><E025 1><E335>Ouip, <E049><E003 8>c'est vrai,<E049><E003 6><E025 2> elle l'est !<E049><E003 16>\r\n<E025 3>J'devrais...<E049><E003 16><E025 2><E341>sans doute point m'inquiéter...");
                R(ref s, "Well in that case, <E049><E003 6><E025 2>do you think perhaps you could\r\nconcentrate on the testimony?", "Eh bien dans ce cas, <E049><E003 6><E025 2>pensez-vous pouvoir vous concentrer\r\nsur la déposition ?");
                return s;
            };

            // [47] BB\script\output\_sce04_c401_0020_eng#18
            entryTranslators[@"BB\script\output\_sce04_c401_0020_eng#18"] = (s) => {
                R(ref s, "Mr Vigil!<E049><E003 10> Is something wrong?", "Monsieur Vigil !<E049><E003 10> Il y a un souci ?");
                R(ref s, "Oh no!<E049><E003 12>\r\nYou, <E049><E003 8><E330>you haven't lost your memory again, <E003 4>have you?", "Oh non !<E049><E003 12>\r\nVous... <E049><E003 8><E330>vous n'avez pas encore perdu la mémoire, <E003 4>j'espère ?");
                R(ref s, "No no, <E049><E003 6>not at all.<E049><E003 12> I was merely in a brown study.", "Non, non, <E049><E003 6>pas du tout.<E049><E003 12> J'étais seulement plongé dans de sombres pensées.");
                R(ref s, "...You can think about how you want to decorate your\r\nhouse later.<E049><E003 10> <E025 3>For now, <E049><E003 6>please focus on the testimony.", "...Vous pourrez réfléchir à la décoration de votre maison\r\nplus tard.<E049><E003 10> <E025 3>Pour l'heure, <E049><E003 6>veuillez vous concentrer sur la déposition.");
                R(ref s, "So sorry...", "Toutes mes excuses...");
                return s;
            };

            // [48] BB\script\output\_sce04_c401_0020_eng#19
            entryTranslators[@"BB\script\output\_sce04_c401_0020_eng#19"] = (s) => {
                R(ref s, "Lord van Zieks!", "Lord Van Peers !");
                R(ref s, "Let me guess:<E049><E003 10> <E238><E025 2>is there something about the witness's last\r\nstatement that troubles me?", "Laissez-moi deviner :<E049><E003 10> <E238><E025 2>y a-t-il quelque chose dans la dernière déclaration\r\ndu témoin qui me tourmente ?");
                R(ref s, "Is that what you wish to ask?", "Est-ce là ce que vous souhaitez me demander ?");
                R(ref s, "Y-<E049><E003 6>Yes...<E003 12> Exactly...<E049><E003 8><E145 1 64><E003 8>\r\n<E025 2>You're very perceptive.", "O... <E049><E003 6>Oui...<E003 12> Exactement...<E049><E003 8><E145 1 64><E003 8>\r\n<E025 2>Vous êtes très perspicace.");
                R(ref s, "Whereas you...<E003 12><E025 3>would appear not to be.", "Tandis que vous...<E003 12><E025 3>semblez ne point l'être.");
                R(ref s, "You really need to learn how to read your fellow man...<E049><E003 12>\r\n<E025 3>my Nipponese friend.", "Il vous faudrait vraiment apprendre à percer vos semblables à jour...<E049><E003 12>\r\n<E025 3>mon cher ami nippon.");
                R(ref s, "(...Read them...<E003 12>or ‘reap’ them?)", "(...Les percer à jour...<E003 12>ou les faucher ?)");
                return s;
            };

            // [49] BB\script\output\_sce04_c401_0020_eng#20
            entryTranslators[@"BB\script\output\_sce04_c401_0020_eng#20"] = (s) => {
                R(ref s, "Mr Vigil!<E049><E003 10> <E025 2>Is something wrong?", "Monsieur Vigil !<E049><E003 10> <E025 2>Quelque chose ne va pas ?");
                R(ref s, "Uuugh...<E049><E003 15><E145 126 75><E025 1><E346>uuuwaaaaaagh!<E049><E003 20>\r\n<E025 1><E331>Yes, sir?<E049><E003 16> What can I do for you, sir?", "Arrrgh...<E049><E003 15><E145 126 75><E025 1><E346>aaah ouuaaaagh !<E049><E003 20>\r\n<E025 1><E331>Oui, chef ?<E049><E003 16> Que puis-je faire pour vous, chef ?");
                R(ref s, "(He's saluting now?)", "(Il fait le salut militaire, maintenant ?)");
                R(ref s, "(What is it?<E003 12> Some sort of Barclay <E006>convention<E007>?)", "(Qu'est-ce que c'est ?<E003 12> Une sorte de <E006>coutume<E007> de Barclay ?)");
                R(ref s, "What Governor Caidin was just saying <E049><E003 6>seemed to upset\r\nyou.", "Ce que le directeur Caidin vient de dire <E049><E003 6>semble vous avoir\r\nbouleversé.");
                R(ref s, "Did it bring something to mind, <E049><E003 6>perhaps?", "Cela vous a-t-il rappelé quelque chose, <E049><E003 6>peut-être ?");
                R(ref s, "For the last ten years, <E049><E003 10>I've completely blotted out the\r\nmemories of that time from my mind.", "Ces dix dernières années, <E049><E003 10>j'avais complètement refoulé de mon\r\nesprit les souvenirs de cette période.");
                R(ref s, "I was betrayed by my superiors...<E003 14><E025 3>in the name of my\r\ncountry.", "J'ai été trahi par mes supérieurs...<E003 14><E025 3>au nom de ma\r\npatrie.");
                R(ref s, "Just as my father was betrayed, <E049><E003 6>it seems.", "Tout comme mon père a été trahi, <E049><E003 6>semble-t-il.");
                R(ref s, "But you see...<E049><E003 14>thinking back now...", "Mais voyez-vous...<E049><E003 14>en y repensant à présent...");
                R(ref s, "...I really can't imagine that the shooting of Mr Asogi in\r\nthe cemetery was ever part of the plan.", "...je ne peux vraiment pas concevoir que l'assassinat de M. Asogi dans\r\nle cimetière ait jamais fait partie du plan.");
                R(ref s, "What makes you think that?", "Qu'est-ce qui vous fait penser cela ?");
                R(ref s, "Well, <E049><E003 10><E025 2>it just doesn't make sense, <E049><E003 8>does it?", "Eh bien, <E049><E003 10><E025 2>cela n'a aucun sens, <E049><E003 8>n'est-ce pas ?");
                R(ref s, "To make the man admit to crimes he didn't commit with\r\nthe promise of a jailbreak, <E049><E003 10><E025 3>only to kill him in the end...", "Pousser cet homme à s'accuser de crimes qu'il n'a pas commis sous la promesse\r\nd'une évasion, <E049><E003 10><E025 3>pour le tuer à la fin...");
                R(ref s, "That's treachery of the worst kind.<E049><E003 12> <E025 3>But the point is,<E049><E003 8> if the\r\nintention was always to betray him...", "C'est une traîtrise de la pire espèce.<E049><E003 12> <E025 3>Mais le fait est que,<E049><E003 8> si l'intention\r\navait toujours été de le trahir...");
                R(ref s, "...why would there be any need for all the chicaneries of\r\n<E006>an escape<E005>?", "...quel besoin y avait-il de monter toute cette mascarade\r\nd'<E006>évasion<E005> ?");
                R(ref s, "Yes!<E049><E003 10> <E145 9 92><E117 9 10><E003 5><E025 1><E346>That's quite true!", "Oui !<E049><E003 10> <E145 9 92><E117 9 10><E003 5><E025 1><E346>C'est tout à fait vrai !");
                R(ref s, "If whoever negotiated with Asogi never intended to keep\r\nhis or her end of the bargain...", "Si la personne ayant négocié avec Asogi n'avait jamais eu l'intention d'honorer\r\nsa part du marché...");
                R(ref s, "...it would have been far simpler just to let the man be\r\nexecuted in prison as dictated by his sentence.", "...il eût été bien plus simple de laisser cet homme être\r\nexécuté en prison comme l'exigeait sa sentence.");
                R(ref s, "...It all happened in that vast chamber of secrets that is\r\nBarclay, <E049><E003 6>behind the high prison walls.", "...Tout cela s'est passé dans cette immense chambre des secrets qu'est\r\nBarclay, <E049><E003 6>derrière les hauts murs de la prison.");
                R(ref s, "I suppose nobody knows what really went on in the\r\nexecution room now...", "J'imagine que personne ne sait ce qui s'est réellement passé dans la\r\nsalle d'exécution à présent...");
                R(ref s, "Yes, <E049><E003 8><E025 2>it's an unsettling mystery, <E049><E003 6>certainly.", "Oui, <E049><E003 8><E025 2>c'est un mystère bien troublant, <E049><E003 6>assurément.");
                R(ref s, "Truth be told...<E049><E003 14><E238>there is a wee matter that's never quite\r\nmade sense to me.", "À vrai dire...<E049><E003 14><E238>y a un p'tit détail qui a jamais collé\r\ndans ma tête.");
                R(ref s, "If you believe there was some kind of negotiation behind\r\nthe jailbreak, <E049><E003 8>atween Asogi and a body at the top...", "Si vous croyez qu'y a eu des négociations pour cette évasion,\r\n<E049><E003 8>entre Asogi et un ponte du sommet...");
                R(ref s, "...it does'nae quite add up, <E049><E003 10>does it?", "...ça colle point tout à fait, <E049><E003 10>n'est-ce pas ?");
                R(ref s, "Governor Caidin, <E049><E003 10><E145 1 7><E025 2>I must insist that you explain these\r\ndoubts that you have...", "Directeur Caidin, <E049><E003 10><E145 1 7><E025 2>j'exige que vous nous fassiez part\r\nde ces doutes...");
                R(ref s, "...by amending your formal testimony!", "...en modifiant votre déposition formelle !");
                R(ref s, "Gads!<E049><E003 12> <E145 127 64><E118 127 0.5><E003 10><E025 3>...Aye, <E049><E003 8><E025 2>go on then.", "Sapristi !<E049><E003 12> <E145 127 64><E118 127 0.5><E003 10><E025 3>...Ouip, <E049><E003 8><E025 2>très bien.");
                return s;
            };

            // [50] BB\script\output\_sce04_c401_0020_eng#29
            entryTranslators[@"BB\script\output\_sce04_c401_0020_eng#29"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu assez de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît clairement <E049><E003 8><E025 2>que toute nouvelle discussion sur cette affaire sera\r\nstérile.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Drake Van Peers, <E049><E003 8><E025 2>j'aimerais croire que, si fourvoyé fussiez-vous...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "...vous avez néanmoins agi par sens de la justice.<E049><E003 12>\r\n<E025 3>Bien qu'il me soit douloureux d'en arriver à cette conclusion...");
                R(ref s, "No!<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Wait, My Lord!", "Non !<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de ce tribunal, <E049><E003 6><E025 3>je déclare\r\nici l'accusé, <E049><E003 6><E025 3>Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "Ceci clôt les débats.<E049><E003 10>\r\n<E025 2>L'audience est levée !");
                return s;
            };

            // [51] BB\script\output\_sce04_c401_0030_eng#2
            entryTranslators[@"BB\script\output\_sce04_c401_0030_eng#2"] = (s) => {
                R(ref s, "Confessing under oath to murders he didn't commit on a\r\nverbal assurance of later being broken out of prison...", "Avouer sous serment des meurtres qu'il n'avait pas commis sur la simple\r\npromesse verbale d'une évasion ultérieure...");
                R(ref s, "Genshin Asogi was taking an incredibly risky gamble.", "Genshin Asogi prenait là un risque insensé.");
                R(ref s, "Very true.", "C'est indéniable.");
                R(ref s, "There was nothing to stop the British breaking their word\r\nand executing him behind closed doors anyway.", "Rien n'empêchait les Britanniques de trahir leur parole\r\net de l'exécuter à huis clos malgré tout.");
                R(ref s, "Under normal circumstances, <E049><E003 8>no man would stake his\r\nlife on a gentleman's agreement like that.", "En temps normal, <E049><E003 8>aucun homme ne risquerait sa\r\nvie sur un simple accord de principe comme celui-là.");
                R(ref s, "Which means that <E049><E003 10><E333><E025 3>Mr Asogi must have had a trump card.", "Ce qui signifie que <E049><E003 10><E333><E025 3>M. Asogi devait détenir un atout majeur.");
                R(ref s, "Something that guaranteed he wouldn't be betrayed.<E049><E003 10><E164 1 8 1 2 8 0 1 1><E139 1>\r\n<E025 1>Some kind of <E006>weapon<E005>!", "Quelque chose qui lui garantissait de ne pas être trahi.<E049><E003 10><E164 1 8 1 2 8 0 1 1><E139 1>\r\n<E025 1>Une forme d'<E006>arme<E005> !");
                R(ref s, "Havers!<E049><E003 16> <E338><E341><E025 1>The fella could'nae possibly have had anythin'\r\nlike that!", "Sottises !<E049><E003 16> <E338><E341><E025 1>L'bonhomme n'aurait jamais pu avoir une chose\r\npareille !");
                R(ref s, "But you know that he did, <E049><E003 6>Governor.", "Mais vous savez fort bien qu'il en avait une, <E049><E003 6>Monsieur le Directeur.");
                R(ref s, "The Asogi Papers –<E049><E003 12> <E025 2>the name given to <E006>the last will and\r\ntestament<E005> of Genshin Asogi.", "Les documents d'Asogi –<E049><E003 12> <E025 2>le nom attribué au <E006>testament<E005>\r\nde Genshin Asogi.");
                R(ref s, "It turns out that Mr Asogi was hiding his will in his cell\r\nat Barclay.", "Il s'avère que M. Asogi dissimulait son testament dans sa cellule\r\nde Barclay.");
                R(ref s, "Chief Warder Vigil caught him with it one day.", "Le gardien-chef Vigil l'a surpris avec, un jour.");
                R(ref s, "You...<E049><E003 20><E145 127 98><E145 126 98><E130 9 0><E003 15><E045><E180><E025 1><E339>you squealed, <E049><E003 10>did ya, ya wee rat!<E049><E003 15>\r\n<E264 127 1.2><E264 126 1.2><E046>Did I no tell ya to keep that a secret?!", "Espèce de...<E049><E003 20><E145 127 98><E145 126 98><E130 9 0><E003 15><E045><E180><E025 1><E339>t'as cafté, <E049><E003 10>hein, sale p'tit rat !<E049><E003 15>\r\n<E264 127 1.2><E264 126 1.2><E046>J't'avais point dit d'garder ça secret ?!");
                R(ref s, "You, <E049><E003 15><E025 1><E264 127 1.5><E264 126 1.5><E607><E339>you can't touch me now!", "Vous... <E049><E003 15><E025 1><E264 127 1.5><E264 126 1.5><E607><E339>vous ne pouvez plus me toucher à présent !");
                R(ref s, "When Mr Vigil caught sight of that will through the bars\r\nof the convict's cell...", "Quand M. Vigil a aperçu ce testament à travers les barreaux\r\nde la cellule du condamné...");
                R(ref s, "...Mr Asogi pleaded with the warder:", "...M. Asogi a supplié le gardien :");
                R(ref s, "Alright then.<E049><E003 12>\r\nBut what's on that paper?", "Soit.<E049><E003 12>\r\nMais qu'y a-t-il sur ce papier ?");
                R(ref s, "...A last will and testament.", "...Un testament.");
                R(ref s, "This will is...<E003 10><E025 3><E086 2 36><E354>the only weapon I have left now.", "Ce testament est...<E003 10><E025 3><E086 2 36><E354>la seule arme qu'il me reste désormais.");
                return s;
            };

            // [52] BB\script\output\_sce04_c401_0030_eng#3
            entryTranslators[@"BB\script\output\_sce04_c401_0030_eng#3"] = (s) => {
                R(ref s, "A weapon...?", "Une arme... ?");
                R(ref s, "And after the convict had been killed following the\r\nelaborate pretence of the jailbreak...", "Et après que le condamné a été tué au terme de ce simulacre\r\nd'évasion sophistiqué...");
                R(ref s, "...that document mysteriously disappeared, <E049><E003 8>didn't it?", "...ce document a mystérieusement disparu, <E049><E003 8>n'est-ce pas ?");
                R(ref s, "W-<E049><E003 10>Well yes...<E049><E003 14><E025 2>all the prison warders searched through the\r\nbelongings in his cell, <E049><E003 8><E025 3>but...", "E... <E049><E003 10>Eh bien oui...<E049><E003 14><E025 2>tous les gardiens ont fouillé ses\r\neffets dans sa cellule, <E049><E003 8><E025 3>mais...");
                R(ref s, "...that will was just nowhere to be found.", "...ce testament était rigoureusement introuvable.");
                R(ref s, "As I understand it, <E049><E003 8>an exhaustive search was made for the\r\ndocument –<E049><E003 8> which became known as the Asogi Papers.", "D'après ce que je sais, <E049><E003 8>des fouilles exhaustives ont été menées pour retrouver\r\nce document –<E049><E003 8> désormais appelé les documents d'Asogi.");
                R(ref s, "Governor Caidin...", "Directeur Caidin...");
                R(ref s, "...I believe you ordered your prison staff to find it at all\r\ncosts, <E049><E003 6>didn't you?", "...je crois savoir que vous avez ordonné à vos hommes de le retrouver\r\nà tout prix, <E049><E003 6>n'est-ce pas ?");
                R(ref s, "Would I be right in saying that you knew?", "Aurais-je raison d'affirmer que vous saviez ?");
                R(ref s, "You knew that the so-called Asogi Papers<E049><E003 12><E164 1 8 1 2 8 0 2 1><E139 1> <E025 1>had the\r\npotential to <E006>make great waves<E005> somehow!", "Vous saviez que ces fameux documents d'Asogi<E049><E003 12><E164 1 8 1 2 8 0 2 1><E139 1> <E025 1>avaient le\r\npouvoir de <E006>provoquer un immense scandale<E005> !");
                R(ref s, "Jings!<E049><E003 20> <E345>What the blazes are ya bletherin' aboot?!", "Mince alors !<E049><E003 20> <E345>Qu'est-ce que vous baragouinez là ?!");
                R(ref s, "The, <E049><E003 10><E025 1><E335><E342>the will was found, <E049><E003 10><E145 127 64><E118 127 0.6><E003 6><E025 1><E333><E342>right an' proper...", "Le... <E049><E003 10><E025 1><E335><E342>le testament a été retrouvé, <E049><E003 10><E145 127 64><E118 127 0.6><E003 6><E025 1><E333><E342>en bonne et due forme...");
                R(ref s, "...in the fella's cell where I said it would be!", "...dans la cellule du bonhomme où j'avais dit qu'il serait !");
                R(ref s, "But how can that be?<E049><E003 18>\r\n<E603>Where in his cell?", "Mais comment cela se peut-il ?<E049><E003 18>\r\n<E603>Où dans sa cellule ?");
                R(ref s, "We all searched the place <E049><E003 2><E160 126><E118 126 1.2><E003 15><E025 1><E606>from top to bottom!", "Nous avons tous fouillé la pièce <E049><E003 2><E160 126><E118 126 1.2><E003 15><E025 1><E606>de fond en comble !");
                R(ref s, "Well ya did'nae do a proper job, <E049><E003 8><E025 2>eh, <E049><E003 10><E264 127 1.3><E264 126 1.3><E346><E025 1>ya peelie-wally\r\ngaloot!", "Eh ben vous avez bâclé l'travail, <E049><E003 8><E025 2>ouip, <E049><E003 10><E264 127 1.3><E264 126 1.3><E346><E025 1>espèce d'andouille\r\nmalingre !");
                R(ref s, "You, <E049><E003 15><E025 1><E264 127 1.5><E264 126 1.5><E603><E339>you can't criticise me now!", "Vous... <E049><E003 15><E025 1><E264 127 1.5><E264 126 1.5><E603><E339>vous ne pouvez plus me critiquer maintenant !");
                R(ref s, "I showed it to ya afore,<E049><E003 8> did I no, <E049><E003 10><E025 1><E346><E264 127 1.8><E264 126 1.8>yon lawyer?", "J'vous l'ai montré autrefois, <E049><E003 8>n'est-ce point, <E049><E003 10><E025 1><E346><E264 127 1.8><E264 126 1.8>maître l'avocat ?");
                R(ref s, "Yes, <E049><E003 8>you did.<E049><E003 10> <E025 2><E060 0 146 1 0><E145 1 20><E003 5>I have the document here.", "Oui, <E049><E003 8>en effet.<E049><E003 10> <E025 2><E060 0 146 1 0><E145 1 20><E003 5>J'ai le document avec moi.");
                R(ref s, "It's written in Japanese, and reads:<E049><E003 15>\r\n<E025 3>‘The Last Will and Testament of Genshin Asogi’.", "Il est rédigé en japonais et porte l'inscription :<E049><E003 15>\r\n<E025 3>« Testament de Genshin Asogi ».");
                R(ref s, "Which means <E049><E003 12><E145 61 5><E239><E025 2>everything is as it should be.", "Ce qui signifie que <E049><E003 12><E145 61 5><E239><E025 2>tout est conforme à ce qui devait être.");
                R(ref s, "Not quite, <E003 4>My Lord.<E049><E003 10> <E025 3>You see, <E049><E003 6><E025 2><E145 1 0><E118 1 1.3><E003 15><E333>there's an undeniable\r\n<E006>inconsistency<E005> here.", "Pas tout à fait, <E003 4>Votre Honneur.<E049><E003 10> <E025 3>Voyez-vous, <E049><E003 6><E025 2><E145 1 0><E118 1 1.3><E003 15><E333>il y a une indéniable\r\n<E006>incohérence<E005> ici.");
                R(ref s, "What?!<E049><E003 16>\r\n<E025 2>What inconsistency?", "Quoi ?!<E049><E003 16>\r\n<E025 2>Quelle incohérence ?");
                R(ref s, "Mr Asogi described this document as the only weapon he\r\nhad left.", "M. Asogi a qualifié ce document de seule arme qu'il lui\r\nrestait.");
                R(ref s, "And yet <E049><E003 10><E025 3><E330>this will contains nothing of significance at all.<E049><E003 12>\r\n<E025 2>Nothing that would have given the convict any leverage.", "Et pourtant, <E049><E003 10><E025 3><E330>ce testament ne contient rigoureusement rien de probant.<E049><E003 12>\r\n<E025 2>Rien qui eût pu lui conférer le moindre moyen de pression.");
                R(ref s, "Are you suggesting, <E049><E003 8>my learned friend...", "Suggéreriez-vous, <E049><E003 8>mon cher confrère...");
                R(ref s, "...that the last will and testament stored at Barclay Prison\r\nall these years...", "...que le testament conservé à la prison de Barclay\r\ntoutes ces années...");
                R(ref s, "...is actually <E006>a fake<E005>?", "...est en réalité <E006>un faux<E005> ?");
                R(ref s, "As has clearly been demonstrated already...", "Comme nous venons de le démontrer sans ambiguïté...");
                R(ref s, "...what went on at Barclay Prison...<E049><E003 12><E164 1 8 1 2 5 0 2 1><E139 1><E025 1>was far from above\r\nboard!", "...ce qui s'est tramé à la prison de Barclay...<E049><E003 12><E164 1 8 1 2 5 0 2 1><E139 1><E025 1>était bien loin d'être\r\nirréprochable !");
                return s;
            };

            // [53] BB\script\output\_sce04_c401_0030_eng#4
            entryTranslators[@"BB\script\output\_sce04_c401_0030_eng#4"] = (s) => {
                R(ref s, "That last vilification by the defence <E049><E003 10><E025 3><E338><E341>was an affront to the\r\nentire British legal system.", "Cette dernière calomnie de la défense <E049><E003 10><E025 3><E338><E341>est un affront envers\r\ntout le système juridique britannique.");
                R(ref s, "This absurd notion of a ‘weapon’ <E049><E003 10><E025 2>is something for which\r\nwe have only the former chief warder's word.", "Cette idée saugrenue d'une « arme » <E049><E003 10><E025 2>ne repose que sur\r\nla parole de l'ancien gardien-chef.");
                R(ref s, "The man could quite easily be lying.<E049><E003 10> <E025 2>Or at the very least,<E049><E003 10><E025 3>\r\nsorely mistaken.", "Cet homme pourrait fort bien mentir.<E049><E003 10> <E025 2>Ou, à tout le moins,<E049><E003 10><E025 3>\r\nse tromper lourdement.");
                R(ref s, "What?<E049><E003 10> <E145 126 68><E118 126 1.2><E003 15><E025 1><E335>No!<E049><E003 14>\r\n<E025 2>I, <E049><E003 10><E025 1><E342>I definitely heard him say that!<E049><E003 14> <E045>I swear!", "Quoi ?<E049><E003 10> <E145 126 68><E118 126 1.2><E003 15><E025 1><E335>Non !<E049><E003 14>\r\n<E025 2>Je... <E049><E003 10><E025 1><E342>je l'ai indubitablement entendu le dire !<E049><E003 14> <E045>Je le jure !");
                R(ref s, "Clearly we need to get to the bottom of this.", "Il est clair que nous devons tirer cela au clair.");
                R(ref s, "We need to know exactly what happened <E049><E003 8><E164 112 7 1 2 5 0 2 1><E139 112><E025 1>with these\r\nso-called Asogi Papers!", "Nous devons savoir exactement ce qui s'est passé <E049><E003 8><E164 112 7 1 2 5 0 2 1><E139 112><E025 1>au sujet de ces\r\nprétendus documents d'Asogi !");
                R(ref s, "A waste of time!<E049><E003 15>\r\n<E025 3>...If the will was fake, <E049><E003 8>where is the real document?", "Perte de temps !<E049><E003 15>\r\n<E025 3>...Si ce testament était un faux, <E049><E003 8>où se trouve le vrai document ?");
                R(ref s, "Mr Vigil was stabbed in the back by the judiciary ten\r\nyears ago.<E049><E003 6> <E145 1 7><E118 1 0.8><E003 10><E330><E025 2>He lost everything.<E049><E003 8> Very nearly his own life.", "M. Vigil a été poignardé dans le dos par l'appareil judiciaire il y a\r\ndix ans.<E049><E003 6> <E145 1 7><E118 1 0.8><E003 10><E330><E025 2>Il a tout perdu.<E049><E003 8> Y compris presque sa propre vie.");
                R(ref s, "And now you're going to do it again.", "Et maintenant, vous vous apprêtez à recommencer.");
                R(ref s, "You're ready to brand him a liar <E049><E003 12><E346><E342>and turn your back on\r\nhim without even letting him defend himself!", "Vous êtes prêt à le traiter de menteur <E049><E003 12><E346><E342>et à lui tourner le dos\r\nsans même lui laisser l'occasion de se défendre !");
                R(ref s, "It's clear that Barclay Prison is hiding something.", "Il est clair que la prison de Barclay dissimule quelque chose.");
                R(ref s, "It's clear that the jailbreak was masterminded\r\n<E042><CNTR>by somebody in the Prosecutor's Office.", "Il est clair que l'évasion a été orchestrée\r\n<E042><CNTR>par quelqu'un au sein du Parquet général.");
                R(ref s, "It's clear that some illicit negotiations took place.", "Il est clair que des négociations illicites ont eu lieu.");
                R(ref s, "...Is Your Lordship just going to gloss over\r\n<E042><CNTR>these obvious and reprehensible facts?!", "...Votre Seigneurie va-t-elle simplement passer sous silence\r\n<E042><CNTR>ces faits aussi flagrants que répréhensibles ?!");
                R(ref s, "What did you say?!", "Qu'avez-vous dit ?!");
                R(ref s, "We should hear more from the chief warder.", "Nous devrions entendre davantage le gardien-chef.");
                R(ref s, "Have him testify again!", "Qu'il dépose à nouveau !");
                R(ref s, "The trial must go on!<E003 25>\r\n<E042><CNTR><E338><E342>The man's voice must be heard!", "Le procès doit continuer !<E003 25>\r\n<E042><CNTR><E338><E342>La voix de cet homme doit être entendue !");
                R(ref s, "It would seem that a vocal few here are utterly blind to\r\nthe truth.", "Il semblerait que quelques esprits bruyants ici soient totalement aveugles\r\nà la vérité.");
                R(ref s, "...Very well then!<E049><E003 15>\r\n<E025 2>Let the witness testify again.", "...Fort bien, alors !<E049><E003 15>\r\n<E025 2>Que le témoin dépose à nouveau.");
                R(ref s, "Tell the court precisely what you think you saw <E049><E003 10><E025 1><E092 1><E046><E339>of the\r\nconvict's last will and testament!", "Dites au tribunal précisément ce que vous croyez avoir vu <E049><E003 10><E025 1><E092 1><E046><E339>du\r\ntestament du condamné !");
                R(ref s, "Yes, sir, <E049><E003 16>My Lord!", "Oui, chef, <E049><E003 16>Votre Honneur !");
                return s;
            };

            // [54] BB\script\output\_sce04_c402_0000_eng#2
            entryTranslators[@"BB\script\output\_sce04_c402_0000_eng#2"] = (s) => {
                R(ref s, "– The Asogi Papers –", "– Les documents d'Asogi –");
                R(ref s, "As the warder responsible for condemned convicts,<E049><E003 8> I\r\nattended to Mr Asogi and kept watch over his cell.", "En tant que gardien responsable des condamnés à mort,<E049><E003 8> je\r\nveillais sur M. Asogi et surveillais sa cellule.");
                R(ref s, "The night after he was found guilty in court, <E049><E003 12><E331><E025 1>he was doing\r\nsomething with that will in his cell!", "La nuit qui a suivi sa condamnation au tribunal, <E049><E003 12><E331><E025 1>il manipulait\r\nce testament dans sa cellule !");
                R(ref s, "We turned the cell inside out looking for it after the\r\nexecution, <E049><E003 8><E025 3>but to no avail.", "Nous avons retourné la cellule pour le chercher après\r\nl'exécution, <E049><E003 8><E025 3>mais en vain.");
                R(ref s, "I only found oot about the Asogi Papers when a directive\r\ncame tellin' me to impound them.", "J'ai seulement su pour les documents d'Asogi lorsqu'une directive\r\nm'a ordonné de les confisquer.");
                R(ref s, "The document was in the folds of the fella's robe that was\r\nleft in his cell.<E049><E003 8> A ‘kimono’, <E049><E003 6>I think it's called.", "Le document s'trouvait dans les plis du vêtement que l'gars avait\r\nlaissé dans sa cellule.<E049><E003 8> Un « kimono », <E049><E003 6>si j'ne m'trompe.");
                return s;
            };

            // [55] BB\script\output\_sce04_c402_0000_eng#3
            entryTranslators[@"BB\script\output\_sce04_c402_0000_eng#3"] = (s) => {
                R(ref s, "In his kimono?!<E049><E003 12>\r\n<E338><E341><E025 2>That's...<E049><E003 15><E025 1><E145 126 99><E117 126 10><E046><E025 1>that's a lie!", "Dans son kimono ?!<E049><E003 12>\r\n<E338><E341><E025 2>C'est...<E049><E003 15><E025 1><E145 126 99><E117 126 10><E046><E025 1>c'est un mensonge !");
                R(ref s, "We searched every inch of the man's cell.<E049><E003 14>\r\n<E025 1>We looked through all his clothes!<E049><E003 15> <E025 1><E145 126 99><E117 126 10><E046>It can't be true!", "Nous avons fouillé chaque recoin de sa cellule !<E049><E003 14>\r\n<E025 1>Nous avons inspecté tous ses vêtements !<E049><E003 15> <E025 1><E145 126 99><E117 126 10><E046>C'est impossible !");
                R(ref s, "Were you no satisfied wi' callin' me a liar the once, <E049><E003 8><E025 3>eh,<E049><E003 10>\r\n<E025 1>ya wee waffinger?", "Ça t'suffisait point d'me traiter d'menteur une fois, <E049><E003 8><E025 3>hein,<E049><E003 10>\r\n<E025 1>espèce de jean-foutre ?");
                R(ref s, "Hah!<E049><E003 12> <E025 2>There's nothing you can do about it now.<E049><E003 12>\r\n<E341><E025 2>You don't have any hold over me any more.", "Ha !<E049><E003 12> <E025 2>Vous ne pouvez plus rien contre moi désormais.<E049><E003 12>\r\n<E341><E025 2>Vous n'avez plus la moindre prise sur moi.");
                R(ref s, "Other than the hold you like to take on my cravat, <E049><E003 8>of\r\ncourse.<E049><E003 10> Is that what you're going to do, <E049><E003 6>is it?", "Hormis la prise que vous aimez tant avoir sur ma cravate, <E049><E003 8>bien\r\nsûr.<E049><E003 10> C'est ce que vous comptez faire, <E049><E003 6>n'est-ce pas ?");
                R(ref s, "Are you going to give me a good shake again?<E049><E003 15>\r\n<E044><E025 2><E264 126 1.5>...Or are you too scared?", "Allez-vous encore me secouer comme un prunier ?<E049><E003 15>\r\n<E044><E025 2><E264 126 1.5>...Ou avez-vous trop peur ?");
                R(ref s, "(Little and large...<E003 12> What a double act.)", "(Le grand et le petit...<E003 12> Quel numéro de duettistes.)");
                R(ref s, "We complied with Asogi's will as far as was possible.", "Nous avons respecté les volontés d'Asogi autant qu'il était possible.");
                R(ref s, "All of his personal effects were delivered to his family\r\nhome in Japan.", "Tous ses effets personnels ont été remis à sa famille\r\nau Japon.");
                R(ref s, "...As a courtesy to the homeland of the most notorious\r\nkiller our country has ever seen.", "...Par courtoisie envers la patrie du plus tristement célèbre\r\ntueur que notre pays ait jamais connu.");
                R(ref s, "And we were much obliged.", "Et nous vous en étions fort reconnaissants.");
                R(ref s, "I can confirm that all of my father's belongings arrived\r\nsafely.", "Je confirme que tous les biens de mon père sont arrivés\r\nà bon port.");
                R(ref s, "Aye, <E049><E003 10><E025 2>and you cannae deny the handwritin' is that of your\r\nold man, <E049><E003 6><E025 3>eh?", "Ouip, <E049><E003 10><E025 2>et vous pouvez point nier que l'écriture est bien celle de votre\r\npaternel, <E049><E003 6><E025 3>hein ?");
                R(ref s, "...Yes, <E049><E003 12><E025 2>there's no mistaking that it's my father's\r\nbrushwork.", "...Oui, <E049><E003 12><E025 2>il est indéniable que c'est le coup de pinceau\r\nde mon père.");
                R(ref s, "And this last will and testament was the man's last\r\n‘weapon’, <E049><E003 6>was it?", "Et ce testament était la dernière « arme » de cet homme,<E049><E003 6> n'est-ce pas ?");
                R(ref s, "I think we can safely assume that the convict was merely\r\nprattling...<E003 12>knowing that his end was nigh.", "Je crois que nous pouvons présumer sans risque que le condamné ne faisait que\r\ndélirer...<E003 12>sachant sa fin imminente.");
                R(ref s, "So, <E049><E003 10><E025 2>Counsel for the Defence...<E049><E003 12>\r\n<E025 2>your cross-examination, please!", "À présent, <E049><E003 10><E025 2>Maître pour la défense...<E049><E003 12>\r\n<E025 2>votre contre-interrogatoire, je vous prie !");
                return s;
            };

            // [56] BB\script\output\_sce04_c402_0010_eng#2
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#2"] = (s) => {
                R(ref s, "– The Asogi Papers –", "– Les documents d'Asogi –");
