                return s;
            };

            // [58] BB\script\output\_sce04_c402_0010_eng#5
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#5"] = (s) => {
                R(ref s, "The night after he was found guilty in court, he was doing\r\nsomething with that will in his cell!", "La nuit qui a suivi sa condamnation au tribunal, il manipulait\r\nce testament dans sa cellule !");
                return s;
            };

            // [59] BB\script\output\_sce04_c402_0010_eng#6
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#6"] = (s) => {
