            // [62] BB\script\output\_sce04_c402_0010_eng#9
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#9"] = (s) => {
                R(ref s, "As I remember it, the document was written in scarlet\r\nink, but...perhaps I'm mistaken.", "Si j'ai bonne mémoire, le document était rédigé à l'encre\r\nécarlate, mais... je me trompe peut-être.");
                return s;
            };

            // [63] BB\script\output\_sce04_c402_0010_eng#10
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#10"] = (s) => {
                R(ref s, "So would that mean that <E049><E003 6><E145 1 85><E003 8><E025 2>you conversed with Mr Asogi?", "Cela voudrait-il dire que <E049><E003 6><E145 1 85><E003 8><E025 2>vous conversiez avec M. Asogi ?");
                R(ref s, "Yes, <E049><E003 10>certainly.<E049><E003 12> <E025 2>Though there was precious little time\r\nbefore his execution was due.", "Oui, <E049><E003 10>absolument.<E049><E003 12> <E025 2>Bien qu'il restât bien peu de temps\r\navant la date fixée pour son exécution.");
                R(ref s, "He was remarkably calm, <E049><E003 8>considering his days were very\r\nmuch numbered.", "Il était remarquablement calme, <E049><E003 8>considérant que ses jours étaient\r\ncomptés.");
                R(ref s, "In all honesty...<E003 16><E330><E025 2>he really didn't strike one as a man\r\ncapable of mass murder.", "En toute franchise...<E003 16><E330><E025 2>il ne donnait absolument pas l'impression d'être\r\ncapable de tueries de masse.");
                R(ref s, "Yet he confessed in full to the crimes.", "Pourtant, il est passé pleinement aux aveux.");
                R(ref s, "I know.<E049><E003 12> <E025 2>That's why I felt compelled to ask him one day.<E049><E003 12>\r\n<E025 3>I can still recall his reply:", "Je sais.<E049><E003 12> <E025 2>C'est pourquoi je me suis senti obligé de lui poser la question.<E049><E003 12>\r\n<E025 3>Je me rappelle encore sa réponse :");
                R(ref s, "‘I'm guilty of the unforgivable crime of ending another\r\nhuman's life, <E049><E003 8>yes.’", "« Je suis coupable du crime impardonnable d'avoir ôté la vie\r\nà un autre être humain, <E049><E003 8>oui. »");
                R(ref s, "But he was so tranquil and intelligent.<E049><E003 8><E144 126>\r\n<E025 2><E238>It put me in mind of an Eastern holy man.", "Mais il était si serein et si intelligent.<E049><E003 8><E144 126>\r\n<E025 2><E238>Il me faisait songer à un saint homme d'Orient.");
                R(ref s, "And what about the will you saw him with?<E049><E003 12>\r\nWhat can you tell us about that?", "Et concernant le testament avec lequel vous l'avez surpris ?<E049><E003 12>\r\nQue pouvez-vous nous en dire ?");
                R(ref s, "It was the beginning of all the drama.<E049><E003 12>\r\n<E025 2>I remember it very well.<E049><E003 10> <E025 3>Yes...", "Ce fut le début de toute la tragédie.<E049><E003 12>\r\n<E025 2>Je m'en souviens très nettement.<E049><E003 10> <E025 3>Oui...");
                return s;
            };

            // [64] BB\script\output\_sce04_c402_0010_eng#11
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#11"] = (s) => {
                R(ref s, "And he pleaded with you not to report him, <E049><E003 6>didn't he?", "Et il vous a supplié de ne pas le dénoncer, <E049><E003 6>n'est-ce pas ?");
                R(ref s, "Yes, <E049><E003 10>that's right.", "Oui, <E049><E003 10>c'est exact.");
                R(ref s, "And like the bampot y'are, <E049><E003 8>ye did'nae tell me.<E049><E003 12>\r\n<E025 2>...A blatant breach of trust, <E049><E003 6>that was.", "Et comme l'andouille que t'es, <E049><E003 8>tu m'as rien dit.<E049><E003 12>\r\n<E025 2>...Un manquement flagrant à la confiance, voilà c'que c'était.");
                R(ref s, "I could see that the man had a noble spirit.<E049><E003 12>\r\n<E025 3>I...<E003 12>found myself wanting to treat him accordingly.", "Je voyais bien que cet homme avait une âme noble.<E049><E003 12>\r\n<E025 3>J'ai...<E003 12>voulu le traiter avec les égards qui lui étaient dus.");
                R(ref s, "But according to what you told us two days ago...", "Pourtant, d'après ce que vous nous avez dit il y a deux jours...");
                R(ref s, "...the convict had been <E171 1 16 0 10 2>strictly forbidden from having any\r\nwriting materials whatsoever.", "...il était <E171 1 16 0 10 2>strictement interdit au détenu de posséder\r\nle moindre matériel d'écriture.");
                R(ref s, "Yes, <E049><E003 12><E025 2>you're quite right.", "Oui, <E049><E003 12><E025 2>vous avez tout à fait raison.");
                R(ref s, "Ah!<E049><E003 10> <E025 2><E145 1 85><E003 10>So when exactly was the will penned?", "Ah !<E049><E003 10> <E025 2><E145 1 85><E003 10>Quand donc ce testament a-t-il été rédigé ?");
                R(ref s, "That was <E006>before<E005> the man was remanded in Barclay,<E049><E003 8>\r\n<E025 3>obviously.", "C'était <E006>avant<E005> que l'homme soit écroué à Barclay,<E049><E003 8>\r\n<E025 3>évidemment.");
                R(ref s, "Yes, <E049><E003 8><E025 2>at the Prosecutor's Office under supervision of the\r\nrelevant authorities.", "Oui, <E049><E003 8><E025 2>au Parquet général sous la surveillance des\r\nautorités compétentes.");
                R(ref s, "I personally instructed Asogi to make a will for the benefit\r\nof his family in his homeland.", "J'ai personnellement ordonné à Asogi de rédiger un testament pour sa\r\nfamille restée dans son pays.");
                R(ref s, "In that case...<E049><E003 14><E330>why was it found in his cell?", "Dans ce cas...<E049><E003 14><E330>pourquoi l'a-t-on retrouvé dans sa cellule ?");
                R(ref s, "W-<E049><E003 10>What do you mean by that?", "Qu... <E049><E003 10>Qu'est-ce que vous entendez par là ?");
                R(ref s, "Well, <E049><E003 8><E025 2>if it was penned at the Prosecutor's Office...", "Eh bien, <E049><E003 8><E025 2>s'il avait été rédigé au Parquet général...");
                R(ref s, "...you would have expected that it would remain there\r\nfor safekeeping, <E049><E003 6><E025 3>surely?", "...on se serait attendu à ce qu'il y reste conservé en\r\nlieu sûr, <E049><E003 6><E025 3>assurément ?");
                R(ref s, "There doesn't seem to be any obvious explanation for\r\nwhy it was subsequently found in the convict's cell.", "Il ne semble y avoir aucune explication logique à la présence\r\nde ce document dans la cellule du détenu par la suite.");
                R(ref s, "Och, <E049><E003 10><E025 3>well...", "Oh, <E049><E003 10><E025 3>eh bien...");
                R(ref s, "The defence makes an astute point.<E049><E003 10>\r\n<E025 3>Well, Governor?", "La défense marque un point judicieux.<E049><E003 10>\r\n<E025 3>Alors, Monsieur le Directeur ?");
                R(ref s, "A prison governor <E049><E003 16><E046><E025 1>cannae be expected to ken the inner\r\nworkings of the Prosecutor's Office.", "On peut point exiger d'un directeur de prison <E049><E003 16><E046><E025 1>qu'il connaisse\r\nles arcanes du Parquet général !");
                R(ref s, "In that case...<E003 12>Lord Stronghart, <E049><E003 8><E025 2>perhaps you can shed some\r\nlight on the matter?", "Dans ce cas...<E003 12>Lord Stronghart, <E049><E003 8><E025 2>peut-être pourriez-vous éclairer\r\nnotre lanterne ?");
                R(ref s, "I'm unable to offer an explanation here and now.", "Je suis dans l'incapacité de vous fournir une explication sur-le-champ.");
                R(ref s, "I would have to consult with the notary responsible for\r\nthe will at the time.", "Il me faudrait consulter le notaire responsable de ce\r\ntestament à l'époque.");
                R(ref s, "The fact that my father's will was discovered in his cell<E049><E003 8><E025 1> is\r\nclearly <E006>inconsistent<E005> with what was expected!", "Le fait que le testament de mon père ait été découvert dans sa cellule<E049><E003 8><E025 1> est\r\nmanifestement <E006>incompatible<E005> avec la procédure habituelle !");
                R(ref s, "...I want to know why.", "...Je veux savoir pourquoi.");
                R(ref s, "(Another inexplicable mystery, then...)", "(Encore un mystère inexplicable, alors...)");
                R(ref s, "Well, <E049><E003 10>um...<E049><E003 16><E025 2>the thing is about that will...", "Eh bien, <E049><E003 10>euh...<E049><E003 16><E025 2>c'est que, concernant ce testament...");
                return s;
            };

            // [65] BB\script\output\_sce04_c402_0010_eng#12
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#12"] = (s) => {
                R(ref s, "It was the governor who ordered the search for the will,\r\nas I understand it.<E049><E003 8> Is that right?", "C'est le directeur qui a ordonné les fouilles pour retrouver le testament,\r\nsi j'ai bien compris.<E049><E003 8> Est-ce exact ?");
                R(ref s, "Yes.<E049><E003 8> <E145 126 64><E118 126 0.5><E003 8><E025 2>And when I reported back that we couldn't find it...", "Oui.<E049><E003 8> <E145 126 64><E118 126 0.5><E003 8><E025 2>Et quand je lui ai fait savoir que nous ne le trouvions pas...");
                R(ref s, "...he grabbed me by the cravat and yelled, <E049><E003 12><E145 126 98><E345><E025 1>‘It cannae have\r\ndisappeared completely!’ <E049><E003 12><E025 2>in my face.", "...il m'a agrippé par la cravate et m'a hurlé : <E049><E003 12><E145 126 98><E345><E025 1>« Il a point pu\r\ndisparaître dans la nature ! » <E049><E003 12><E025 2>au beau milieu du visage.");
                R(ref s, "Aye, <E049><E003 8>well...<E049><E003 12><E025 2>it's doon to the governor to keep everybody\r\nworkin' as hard as they should.", "Ouip, <E049><E003 8>enfin...<E049><E003 12><E025 2>c'est au directeur d'faire en sorte que tout l'monde\r\ns'active comme il faut.");
                R(ref s, "I think the governor needs a ‘wee’ taste of his own\r\nmedicine, Mr Naruhodo!", "Je crois que le directeur aurait bien besoin qu'on lui rende la monnaie\r\nde sa pièce, monsieur Naruhodo !");
                R(ref s, "...The point is, <E049><E003 10><E025 2>it was clearly considered <E145 9 17><E118 9 0.7>a very important\r\ndocument, <E003 6>wasn't it?", "...Le fait est <E049><E003 10><E025 2>qu'on le considérait manifestement <E145 9 17><E118 9 0.7>comme un document\r\ncapital, <E003 6>n'est-ce pas ?");
                R(ref s, "But it proved impossible to find...", "Mais il s'est avéré introuvable...");
                R(ref s, "Then before I knew it, <E049><E003 10>it was in the morning paper.<E049><E003 12>\r\nThat blood-curdling article.", "Puis sans crier gare, <E049><E003 10>c'est paru dans le journal du matin.<E049><E003 12>\r\nCet article à vous glacer le sang.");
                R(ref s, "The executed mass murderer who'd risen from the dead...", "Le tueur de masse exécuté revenu d'entre les morts...");
                R(ref s, "...The article based on Mr Drebber's experience in\r\nLowgate Cemetery!", "...L'article inspiré par la mésaventure de M. Drebber au cimetière\r\nde Lowgate !");
                R(ref s, "The day after I'd read that news, <E049><E003 12><E145 126 71><E003 15><E025 3><E360>I was summoned to the\r\ngovernor's office.", "Le lendemain du jour où j'ai lu cette nouvelle, <E049><E003 12><E145 126 71><E003 15><E025 3><E360>j'ai été convoqué dans le bureau\r\ndu directeur.");
                R(ref s, "And...<E049><E003 12><E025 3><E145 126 74><E003 15><E360>that's when the awful accusation was made.", "Et...<E049><E003 12><E025 3><E145 126 74><E003 15><E360>c'est là que cette terrible accusation a été portée.");
                R(ref s, "That you'd aided Genshin Asogi to escape from the prison,<E049><E003 8>\r\n<E025 3>resulting in your immediate dismissal.", "Que vous aviez aidé Genshin Asogi à s'évader de la prison,<E049><E003 8>\r\n<E025 3>ce qui a provoqué votre renvoi immédiat.");
                R(ref s, "I'm afraid I...<E049><E003 6><E145 126 77><E117 126 25><E003 10><E025 3>I really don't remember anything after that.", "J'ai bien peur que...<E049><E003 6><E145 126 77><E117 126 25><E003 10><E025 3>je ne me souvienne vraiment de rien d'autre après cela.");
                R(ref s, "As the governor of the prison, <E049><E003 8><E025 3>I...<E003 12><E025 3>I had no choice.<E049><E003 12>\r\nI could'nae have done anythin' else.", "En tant que directeur d'la prison, <E049><E003 8><E025 3>je...<E003 12><E025 3>j'avais point l'choix.<E049><E003 12>\r\nJ'pouvais point faire autrement.");
                return s;
            };

            // [66] BB\script\output\_sce04_c402_0010_eng#13
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#13"] = (s) => {
                R(ref s, "And that directive <E049><E003 6><E145 1 0><E118 1 0.7><E149 1 0 8><E003 6>came from the same source as the one\r\ninstructing you about the jailbreak?", "Et cette consigne <E049><E003 6><E145 1 0><E118 1 0.7><E149 1 0 8><E003 6>émanait de la même source que celle\r\nordonnant l'évasion ?");
                R(ref s, "Aye.<E049><E003 16> <E025 2>From the top levels of the Prosecutor's Office.", "Ouip.<E049><E003 16> <E025 2>Des plus hautes sphères du Parquet général.");
                R(ref s, "What name was on it?", "Quel nom figurait dessus ?");
                R(ref s, "I did'nae ken afore <E049><E003 8><E239><E025 3>an' I dinnae ken now.", "J'l'savais point avant, <E049><E003 8><E239><E025 3>et j'l'sais point maintenant.");
                R(ref s, "All I can tell ya, <E049><E003 8><E025 3>is that my orders were to do everythin'\r\nin my power to find that document.", "Tout c'que j'peux vous dire, <E049><E003 8><E025 3>c'est qu'j'avais pour ordre de remuer ciel\r\net terre pour trouver ce document.");
                R(ref s, "The directive said it had to be somewhere inside the\r\nfella's cell.", "La consigne disait qu'il d'vait s'trouver quelqu'part dans la\r\ncellule du type.");
                R(ref s, "Was that the wording?<E049><E003 10> <E025 3>‘Document’ <E049><E003 8>not ‘will’?", "Était-ce le terme employé ?<E049><E003 10> <E025 3>« Document » <E049><E003 8>et non « testament » ?");
                R(ref s, "...Aye, <E049><E003 20>that's what it said.", "...Ouip, <E049><E003 20>c'est c'qui était écrit.");
                R(ref s, "(Am I clutching at straws here...?)", "(Suis-je en train de me raccrocher à des chimères... ?)");
                R(ref s, "(I just wonder <E003 12><E239>if it was really Genshin Asogi's last will and\r\ntestament that the sender of that directive was after...)", "(Je me demande <E003 12><E239>si c'était véritablement le testament de Genshin\r\nAsogi que l'émetteur de cet ordre recherchait...)");
                R(ref s, "Continue with your testimony then, <E049><E003 4>witness.", "Poursuivez votre déposition, <E049><E003 4>témoin.");
                return s;
            };

            // [67] BB\script\output\_sce04_c402_0010_eng#14
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#14"] = (s) => {
                R(ref s, "In <E145 1 0><E118 1 1.25><E149 1 0 8>Mr Asogi's kimono?", "Dans <E145 1 0><E118 1 1.25><E149 1 0 8>le kimono de M. Asogi ?");
                R(ref s, "Aye, <E049><E003 14><E025 2>the one he'd brought with him when he was locked\r\nup.", "Ouip, <E049><E003 14><E025 2>celui qu'il avait apporté avec lui quand on l'a enfermé.");
                R(ref s, "Yes...<E003 8><E145 1 66><E003 8><E025 2>he was permitted to have his personal effects with\r\nhim during his incarceration, <E049><E003 6>I understand?", "Oui...<E003 8><E145 1 66><E003 8><E025 2>on l'a autorisé à conserver ses effets personnels avec\r\nlui durant son incarcération, <E049><E003 6>si je comprends bien ?");
                R(ref s, "That's right.<E049><E003 12> He was granted as much freedom as possible\r\nduring the few days before his execution.", "C'est exact.<E049><E003 12> On lui a accordé autant de liberté que possible\r\ndurant les quelques jours précédant son exécution.");
                R(ref s, "Indeed.<E049><E003 12> He had a number of items of personal significance,<E049><E003 8>\r\nI remember.", "En effet.<E049><E003 12> Il possédait plusieurs objets d'une grande valeur affective,<E049><E003 8>\r\nsi j'ai bonne mémoire.");
                R(ref s, "He was very reluctant to part with them.<E049><E003 12>\r\n<E025 3><E239>Some books, <E049><E003 15><E145 126 71><E118 126 1.3><E003 15>that kimono, <E049><E003 15><E145 126 74><E118 126 1.3><E003 15><E238>his sword...", "Il répugnait beaucoup à s'en séparer.<E049><E003 12>\r\n<E025 3><E239>Quelques livres, <E049><E003 15><E145 126 71><E118 126 1.3><E003 15>ce fameux kimono, <E049><E003 15><E145 126 74><E118 126 1.3><E003 15><E238>son sabre...");
                R(ref s, "His <E006>sword<E005>?!", "Son <E006>sabre<E005> ?!");
                R(ref s, "Karuma, <E049><E003 8>the famous sword of the Asogi clan.<E049><E003 10><E145 112 4><E149 112 0 4><E003 16>\r\n<E025 3><E330>...It bears the soul of my family.", "Karuma, <E049><E003 8>la célèbre lame du clan Asogi.<E049><E003 10><E145 112 4><E149 112 0 4><E003 16>\r\n<E025 3><E330>...Elle porte l'âme de ma famille.");
                R(ref s, "I, <E049><E003 8>I don't doubt it, <E049><E003 10><E341><E025 3>but I wasn't really getting at that...", "Je... <E049><E003 8>je n'en doute pas, <E049><E003 10><E341><E025 3>mais ce n'était pas vraiment là que je voulais en venir...");
                R(ref s, "(Forget it being the soul of the clan!<E003 12>\r\n<E025 2>Could the man have had a more obvious ‘<E006>weapon<E007>’?)", "(Qu'importe l'âme du clan !<E003 12>\r\n<E025 2>Cet homme aurait-il pu posséder une « <E006>arme<E007> » plus évidente ?)");
                R(ref s, "Have some respect, <E049><E003 10>Ryunosuke.", "Fais preuve d'un peu de respect, <E049><E003 10>Ryunosuke.");
                R(ref s, "...Respectful silence?", "...Un silence respectueux ?");
                R(ref s, "The warders carry firearms at all times, <E049><E003 8>and the inmates\r\nhave shackles around their ankles.", "Les gardiens ont des armes à feu en permanence, <E049><E003 8>et les prisonniers\r\nont des fers aux chevilles.");
                R(ref s, "He could'nae have hurt anybody wi' that thing.", "Il n'aurait point pu blesser qui que ce soit avec cet engin.");
                R(ref s, "Still, <E049><E003 4><E145 1 1><E118 1 0.85><E003 8><E025 3>he was allowed a sword, <E049><E003 8>but no writing materials?", "Quand même, <E049><E003 4><E145 1 1><E118 1 0.85><E003 8><E025 3>on lui autorisait une épée, <E049><E003 8>mais pas de matériel d'écriture ?");
                R(ref s, "He wrote that will afore he came to stay wi' us at Barclay,<E003 4>\r\nyou see.", "Il a rédigé ce testament avant de venir séjourner chez nous à Barclay,<E003 4>\r\nvoyez-vous.");
                R(ref s, "Dr Mikotoba was asked <E049><E003 2><E145 61 0><E118 61 0.55><E003 6><E025 2>to bring the necessary Japanese\r\nwriting implements to the Prosecutor's Office.", "On avait demandé au Dr Mikotoba <E049><E003 2><E145 61 0><E118 61 0.55><E003 6><E025 2>d'apporter le matériel de calligraphie\r\njaponais nécessaire au Parquet général.");
                R(ref s, "A suzuri ink stone, <E049><E003 8>black sumi ink <E049><E003 8><E164 9 3 1 2 6 0 0 1><E139 9><E025 2>and some hanshi rice\r\npaper, <E049><E003 6>no doubt.", "Une pierre à encre suzuri, <E049><E003 8>de l'encre noire sumi <E049><E003 8><E164 9 3 1 2 6 0 0 1><E139 9><E025 2>et du papier\r\nde riz hanshi, <E049><E003 6>sans nul doute.");
                R(ref s, "I was present when he wrote it...", "J'étais là quand il l'a écrit...");
                R(ref s, "But I'm sorry to say <E049><E003 20><E145 127 78><E346><E025 1>the letters just looked like a squirmin'\r\nmass of jet-black earthwerums to me.", "Mais j'suis au regret d'vous dire <E049><E003 20><E145 127 78><E346><E025 1>que ces lettres ressemblaient\r\njuste à un grouillement d'vers d'terre noir ébène pour moi.");
                R(ref s, "My father had a passion for calligraphy.<E049><E003 10> He found the\r\nprofound black colour of sumi ink to be very soothing.", "Mon père se passionnait pour la calligraphie.<E049><E003 10> Il trouvait le noir\r\nprofond de l'encre sumi des plus apaisants.");
                R(ref s, "I'm <E145 9 14>sure that cursive Japanese script <E049><E003 8><E330>must look utterly\r\nincomprehensible to English eyes.", "Je suis <E145 9 14>certaine que l'écriture cursive japonaise <E049><E003 8><E330>doit sembler tout à fait\r\nincompréhensible aux yeux d'un Anglais.");
                R(ref s, "Anyhow, <E049><E003 8><E025 2>that's the document that was found in the fella's\r\nkimono.", "Bref, <E049><E003 8><E025 2>c'est bien ce document qui a été retrouvé dans l'kimono\r\ndu lascar.");
                R(ref s, "Despite the seriousness of his crimes, <E049><E003 8>he was treated in a\r\ngentlemanly fashion until the end.", "En dépit de la gravité de ses crimes, <E049><E003 8>il a été traité avec\r\négards et courtoisie jusqu'à la fin.");
                R(ref s, "When he was callously betrayed and shot dead in a dark\r\ncemetery in the middle of the night.", "Au moment où il a été lâchement trahi et abattu dans un sombre\r\ncimetière au milieu de la nuit.");
                R(ref s, "...Yes, <E049><E003 10><E145 112 19><E118 112 1.15><E003 4><E238>the gentlemanliness of it is overwhelming.", "...Oui, <E049><E003 10><E145 112 19><E118 112 1.15><E003 4><E238>la courtoisie d'un tel geste saute aux yeux.");
                return s;
            };

            // [68] BB\script\output\_sce04_c402_0010_eng#17
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#17"] = (s) => {
                R(ref s, "Scarlet, <E049><E003 6>you say?", "Écarlate, <E049><E003 6>dites-vous ?");
                R(ref s, "Well...<E003 12><E025 3><E341>yes.<E049><E003 12> <E025 2>I mean, <E049><E003 8>I only caught sight of it for a brief\r\nmoment, <E049><E003 6>of course.", "Eh bien...<E003 12><E025 3><E341>oui.<E049><E003 12> <E025 2>Je veux dire, <E049><E003 8>je ne l'ai entrevu qu'un bref\r\ninstant, <E049><E003 6>bien entendu.");
                R(ref s, "But even by the dim light in the cell, <E049><E003 12>I remember thinking\r\nthat it was an unusual colour.", "Mais même sous la faible clarté de la cellule, <E049><E003 12>je me rappelle avoir pensé\r\nque c'était une teinte insolite.");
                R(ref s, "At the very least, <E049><E003 10><E145 126 74><E003 10><E238><E025 3>I'm quite sure it wasn't black.", "À tout le moins, <E049><E003 10><E145 126 74><E003 10><E238><E025 3>je suis tout à fait sûr que ce n'était pas noir.");
                R(ref s, "Witness!<E023>\r\n--- PAGE 6 ---\r\n<E800 1169><E041 61 25><E025 1><E046><E339>Is that really what you saw?!", "Témoin !<E023>\r\n--- PAGE 6 ---\r\n<E800 1169><E041 61 25><E025 1><E046><E339>Est-ce vraiment ce que vous avez vu ?!");
                R(ref s, "Ah!<E049><E003 16> <E025 3>Wha...<E049><E003 16>\r\n<E025 1><E145 126 75><E118 126 1.4><E606>Siiiiiir!", "Ah !<E049><E003 16> <E025 3>Quoi...<E049><E003 16>\r\n<E025 1><E145 126 75><E118 126 1.4><E606>Monsieur le Juge en cheeeef !");
                R(ref s, "Is something wrong, <E049><E003 6>Lord Stronghart?", "Un malaise, <E049><E003 6>Lord Stronghart ?");
                R(ref s, "I, <E049><E003 10><E341>I apologise.<E049><E003 20><E145 61 0><E118 61 0.55>\r\n<E025 3>Continue.", "Je... <E049><E003 10><E341>veuillez m'excuser.<E049><E003 20><E145 61 0><E118 61 0.55>\r\n<E025 3>Poursuivez.");
                R(ref s, "What do you make of that, <E049><E003 6>Mr Naruhodo?", "Qu'en pensez-vous, <E049><E003 6>monsieur Naruhodo ?");
                R(ref s, "For Lord Stronghart to be so visibly shaken in that way...", "Pour que Lord Stronghart soit ainsi ébranlé de façon si visible...");
                R(ref s, "Och, <E049><E003 10>dinnae haver!<E049><E003 15> <E060 0 146 0 0><E025 2>You can plainly see the writin' here.<E049><E003 14>\r\n<E025 1><E607>And it's as black as the Earl o' Hell's waistcoat!", "Bah, <E049><E003 10>racontez point d'sornettes !<E049><E003 15> <E060 0 146 0 0><E025 2>Vous voyez bien l'écriture ici.<E049><E003 14>\r\n<E025 1><E607>Et elle est aussi noire que l'âme du Diable !");
                R(ref s, "Mr Vigil, <E049><E003 8><E145 1 0><E149 1 0 8>I'd like to confirm one point with you.", "Monsieur Vigil, <E049><E003 8><E145 1 0><E149 1 0 8>j'aimerais tirer un point au clair avec vous.");
                R(ref s, "Did you actually see <E006>the content<E005> of the document that\r\nMr Asogi was holding that night?", "Avez-vous réellement vu <E006>le contenu<E005> du document que\r\nM. Asogi tenait cette nuit-là ?");
                R(ref s, "Oh!<E049><E003 12> <E341><E025 3>Well, <E049><E003 12><E025 2>no!<E049><E003 14>\r\nI mean, <E049><E003 8>there was no time.", "Oh !<E049><E003 12> <E341><E025 3>Eh bien, <E049><E003 12><E025 2>non !<E049><E003 14>\r\nC'est-à-dire que je n'en ai pas eu le temps.");
                R(ref s, "As soon as he noticed me there, <E049><E003 10><E145 126 66><E118 126 1.3><E025 2>he hid it behind his back.", "Dès qu'il a remarqué ma présence, <E049><E003 10><E145 126 66><E118 126 1.3><E025 2>il l'a dissimulé dans son dos.");
                R(ref s, "But <E145 1 66><E118 1 1.2>it was definitely a will, <E049><E003 6>was it?", "Mais <E145 1 66><E118 1 1.2>il s'agissait bien d'un testament, <E049><E003 6>n'est-ce pas ?");
                R(ref s, "Yes, <E049><E003 8>it was.<E049><E003 12> <E025 2>That's what Mr Asogi told me.", "Oui, <E049><E003 8>absolument.<E049><E003 12> <E025 2>C'est ce que m'a dit M. Asogi.");
                R(ref s, "The court need waste no further time on this matter.", "Le tribunal n'a pas à perdre davantage de temps sur ce point.");
                R(ref s, "We have the will in question in our possession.<E049><E003 12>\r\n<E239>There is nothing more to add.", "Nous avons le testament en question en notre possession.<E049><E003 12>\r\n<E239>Il n'y a rien de plus à ajouter.");
                R(ref s, "(A will written in <E006>scarlet<E007> ink...)", "(Un testament écrit à l'encre <E006>écarlate<E007>...)");
                R(ref s, "(What did Mr Vigil really see Kazuma's father holding,<E003 6> I\r\nwonder...?)", "(Que tenait réellement le père de Kazuma ce soir-là,<E003 6> je me le\r\ndemande...)");
                R(ref s, "If you have an inkling, <E049><E003 6>Mr Naruhodo, <E049><E003 4><E025 1><E164 9 15 1 2 6 0 1 1><E139 9>you must present it\r\nto the court at once!", "Si vous avez une piste, <E049><E003 6>monsieur Naruhodo, <E049><E003 4><E025 1><E164 9 15 1 2 6 0 1 1><E139 9>vous devez la présenter\r\nà la cour sans attendre !");
                return s;
            };

            // [69] BB\script\output\_sce04_c402_0010_eng#18
            entryTranslators[@"BB\script\output\_sce04_c402_0010_eng#18"] = (s) => {
                R(ref s, "(That testimony doesn't give much away.)", "(Cette déposition n'apporte pas grand-chose de nouveau.)");
                R(ref s, "So this will really was penned by Kazuma-sama's father.", "Ce testament a donc bien été rédigé par le père de maître Kazuma.");
                R(ref s, "I wonder what he could possibly have meant when he\r\ndescribed it as a weapon...", "Je me demande bien ce qu'il a pu vouloir dire en le décrivant\r\ncomme une arme...");
                R(ref s, "It's starting to sound very much <E003 8><E330>like Mr Asogi actually\r\nhad <E006>nothing<E005>.", "On commence sérieusement à avoir l'impression <E003 8><E330>que M. Asogi n'avait\r\nen réalité <E006>rien du tout<E005>.");
                R(ref s, "But the plan to break him out of jail went ahead.<E049><E003 10>\r\nWhich means he must have had some bargaining power.", "Pourtant, le plan d'évasion a été enclenché.<E049><E003 10>\r\nCe qui prouve qu'il devait avoir un moyen de pression.");
                R(ref s, "He must have been hiding something.<E049><E003 10>\r\n<E025 2>It's the only explanation that makes sense.", "Il devait dissimuler quelque chose.<E049><E003 10>\r\n<E025 2>C'est la seule explication plausible.");
                R(ref s, "It's...<E003 8><E025 2>starting to sound like Mr Asogi <E003 8><E025 2><E043>actually might have\r\nhad <E006>something<E005>!", "On... <E003 8><E025 2>on dirait presque que M. Asogi <E003 8><E025 2><E043>détenait bel et bien\r\n<E006>quelque chose<E005> !");
                R(ref s, "...Which is it, <E049><E003 8>Mr Naruhodo?", "...Laquelle des deux hypothèses est la bonne, <E049><E003 8>monsieur Naruhodo ?");
                R(ref s, "I'm not sure.<E003 10> But I feel <E145 9 0><E118 9 1.1>as though I'm on the brink of\r\nunderstanding all this.", "Je ne suis pas sûr.<E003 10> Mais j'ai la sensation <E145 9 0><E118 9 1.1>que nous touchons au\r\nbut.");
                R(ref s, "Let's listen to all the information again and see what more\r\nwe can learn.<E003 12> <E025 1><E346>We can't overlook even the smallest detail!", "Réécoutons toutes ces informations et voyons ce que nous pouvons en tirer.<E003 12>\r\n<E025 1><E346>Nous ne pouvons négliger le moindre détail !");
                return s;
            };

            // [70] BB\script\output\_sce04_c402_0010_eng#19
